SUBROUTINE URNG2 (IX, X, Y, N, IERR)
!-----------------------------------------------------------------------
!
!         GENERATION OF UNIFORM RANDOM POINTS (X(I),Y(I))
!                     FOR I = 1,...,N WHERE
!
!                      0 .LT. X(I) .LT. 1
!                      0 .LT. Y(I) .LT. 1
!
!     IT IS ASSUMED THAT 0 .LT. IX .LT. P
!-----------------------------------------------------------------------
!     WRITTEN BY
!        LINUS SCHRAGE
!        UNIVERSITY OF CHICAGO
!     ADAPTED BY A.H. MORRIS (NSWC)
!-------------------
REAL X(N), Y(N)
INTEGER A, B15, B16, FHI, P, XALO, XHI
!-------------------
!     DATA A/7**5/,  B15/2**15/, B16/2**16/, P/2**31 - 1/
!-------------------
DATA A/16807/, B15/32768/, B16/65536/, P/2147483647/
DATA S/.465661E-09/
!-------------------
IF (N .LE. 0) GO TO 100
IF (IX .LE. 0 .OR. IX .GE. P) GO TO 110
IERR = 0
!
!         SEE THE COMMENTS IN THE SUBROUTINE URNG FOR THE
!                STATEMENTS IN THE FOLLOWING LOOP
!
DO L = 1,N
   XHI = IX/B16
   XALO = (IX - XHI*B16)*A
   LEFTLO = XALO/B16
   FHI = XHI*A + LEFTLO
   K = FHI/B15
   IX = (((XALO - LEFTLO*B16) - P) + (FHI - K*B15)*B16) + K
   IF (IX .LT. 0) IX = IX + P
   T = IX
   X(L) = S*T
!
   XHI = IX/B16
   XALO = (IX - XHI*B16)*A
   LEFTLO = XALO/B16
   FHI = XHI*A + LEFTLO
   K = FHI/B15
   IX = (((XALO - LEFTLO*B16) - P) + (FHI - K*B15)*B16) + K
   IF (IX .LT. 0) IX = IX + P
   T = IX
   Y(L) = S*T
END DO
RETURN
!
!                         ERROR RETURN
!
100 IERR = 1
RETURN
110 IERR = 2
RETURN
END SUBROUTINE URNG2

SUBROUTINE DURNG2 (IX, X, Y, N, IERR)
!-----------------------------------------------------------------------
!
!         GENERATION OF UNIFORM RANDOM POINTS (X(I),Y(I))
!                     FOR I = 1,...,N WHERE
!
!                      0 .LT. X(I) .LT. 1
!                      0 .LT. Y(I) .LT. 1
!
!     IT IS ASSUMED THAT 0 .LT. IX .LT. P
!-----------------------------------------------------------------------
!     WRITTEN BY
!        LINUS SCHRAGE
!        UNIVERSITY OF CHICAGO
!     ADAPTED BY A.H. MORRIS (NSWC)
!-------------------
DOUBLE PRECISION X(N), Y(N)
