IERR = 0
!
!         SEE THE COMMENTS IN THE SUBROUTINE DURNG FOR THE
!                 STATEMENTS IN THE FOLLOWING LOOP
!
DO L = 1,N
   XHI = IX/B16
   XALO = (IX - XHI*B16)*A
   LEFTLO = XALO/B16
   FHI = XHI*A + LEFTLO
   K = FHI/B15
   IX = (((XALO - LEFTLO*B16) - P) + (FHI - K*B15)*B16) + K
   IF (IX .LT. 0) IX = IX + P
   T = IX
   X(L) = S*T
!
   XHI = IX/B16
   XALO = (IX - XHI*B16)*A
   LEFTLO = XALO/B16
   FHI = XHI*A + LEFTLO
   K = FHI/B15
   IX = (((XALO - LEFTLO*B16) - P) + (FHI - K*B15)*B16) + K
   IF (IX .LT. 0) IX = IX + P
   T = IX
   Y(L) = S*T
END DO
