!                  CALL TO THE ROUTINE (WHEN MO .NE. 0).
!
!        A       - VARIANCE-COVARIANCE MATRIX OF ORDER M.
!                  A IS A DIAGONAL MATRIX WITH POSITIVE
!                  DIAGONAL ELEMENTS. THE DIAGONAL ELEMENTS
!                  ARE STORED IN THE ARRAY A. A IS AN ARRAY
